"use client";

import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { AddressBadge } from "@/registry/new-york/wallet-card/address-badge";
import {
  NetworkBadge,
  type NetworkName,
} from "@/registry/new-york/wallet-card/network-badge";
import { TokenAmount } from "@/registry/new-york/wallet-card/token-amount";
import { cn } from "@/lib/utils";

export interface WalletBalance {
  symbol: string;
  amount: string;
  usdValue?: string | null;
}

export interface WalletCardProps {
  /** Connected wallet address */
  address: string;
  /** Resolved ENS / StarkNet ID */
  ens?: string | null;
  /** Starknet network */
  network?: NetworkName;
  /** Token balances to display */
  balances?: WalletBalance[];
  /** Show skeleton loading state */
  loading?: boolean;
  /** Called when user clicks Disconnect */
  onDisconnect?: () => void;
  className?: string;
}

/**
 * A card summarising the connected wallet: address, network, balances.
 *
 * Wire up with `useWallet()` from `@dngbuilds/zapkit-react`:
 *
 * @example
 * ```tsx
 * import { useWallet } from "@dngbuilds/zapkit-react";
 * import { WalletCard } from "@/components/wallet-card";
 *
 * const { address, ens, connect, disconnect } = useWallet();
 * <WalletCard address={address!} ens={ens} onDisconnect={disconnect} />
 * ```
 */
export function WalletCard({
  address,
  ens,
  network = "mainnet",
  balances = [],
  loading = false,
  onDisconnect,
  className,
}: WalletCardProps) {
  if (loading) {
    return (
      <Card className={cn("w-72", className)}>
        <CardHeader>
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-3 w-40 mt-1" />
        </CardHeader>
        <CardContent className="flex flex-col gap-2">
          <Skeleton className="h-3 w-full" />
          <Skeleton className="h-3 w-3/4" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={cn("w-72", className)}>
      <CardHeader>
        <div className="flex items-start justify-between gap-2">
          <div className="flex flex-col gap-1.5">
            <CardTitle className="text-sm">Wallet</CardTitle>
            <AddressBadge address={address} ens={ens} />
          </div>
          <NetworkBadge network={network} />
        </div>
        {ens && (
          <CardDescription className="font-mono text-xs">
            {ens}
          </CardDescription>
        )}
      </CardHeader>

      {balances.length > 0 && (
        <>
          <Separator />
          <CardContent className="flex flex-col gap-2 pt-4">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
              Balances
            </p>
            {balances.map((b) => (
              <div
                key={b.symbol}
                className="flex items-center justify-between"
              >
                <span className="text-sm text-muted-foreground">
                  {b.symbol}
                </span>
                <TokenAmount
                  amount={b.amount}
                  symbol={b.symbol}
                  usdValue={b.usdValue}
                  hideSymbol
                  decimals={4}
                />
              </div>
            ))}
          </CardContent>
        </>
      )}

      {onDisconnect && (
        <CardFooter className="pt-0">
          <Button
            variant="ghost"
            size="sm"
            onClick={onDisconnect}
            className="w-full text-muted-foreground hover:text-destructive"
          >
            Disconnect
          </Button>
        </CardFooter>
      )}
    </Card>
  );
}

"use client";

import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { useCallback, useState } from "react";

export interface AddressBadgeProps {
  address: string;
  ens?: string | null;
  className?: string;
}

function truncate(addr: string): string {
  if (addr.length <= 12) return addr;
  return `${addr.slice(0, 6)}…${addr.slice(-4)}`;
}

export function AddressBadge({ address, ens, className }: AddressBadgeProps) {
  const [copied, setCopied] = useState(false);

  const copy = useCallback(() => {
    navigator.clipboard.writeText(address).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  }, [address]);

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            onClick={copy}
            className={cn(
              "inline-flex items-center gap-1 rounded-md border px-2 py-0.5 font-mono text-xs transition-colors hover:bg-accent cursor-pointer select-none",
              className,
            )}
          >
            {ens ?? truncate(address)}
          </button>
        </TooltipTrigger>
        <TooltipContent side="bottom" className="font-mono text-xs">
          {copied ? "Copied!" : address}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type NetworkName = "mainnet" | "sepolia" | "devnet";

const NETWORK_META: Record<NetworkName, { label: string; color: string }> = {
  mainnet: { label: "Mainnet", color: "bg-green-500/15 text-green-700 dark:text-green-400" },
  sepolia: { label: "Sepolia", color: "bg-yellow-500/15 text-yellow-700 dark:text-yellow-400" },
  devnet: { label: "Devnet", color: "bg-blue-500/15 text-blue-700 dark:text-blue-400" },
};

export interface NetworkBadgeProps {
  network?: NetworkName;
  className?: string;
}

export function NetworkBadge({ network = "mainnet", className }: NetworkBadgeProps) {
  const meta = NETWORK_META[network] ?? NETWORK_META.mainnet;

  return (
    <Badge variant="outline" className={cn("text-[10px] font-medium", meta.color, className)}>
      {meta.label}
    </Badge>
  );
}

"use client";

import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

export interface TokenAmountProps {
  /** Raw or pre-formatted token amount */
  amount: string;
  /** Token symbol, e.g. "ETH" */
  symbol: string;
  /** Optional USD value string */
  usdValue?: string | null;
  /** Max decimal places to display (default 6) */
  decimals?: number;
  /** Hide the symbol suffix */
  hideSymbol?: boolean;
  className?: string;
}

function formatAmount(raw: string, decimals: number): string {
  const n = Number(raw);
  if (Number.isNaN(n)) return raw;
  return n.toLocaleString("en-US", {
    minimumFractionDigits: 0,
    maximumFractionDigits: decimals,
  });
}

export function TokenAmount({
  amount,
  symbol,
  usdValue,
  decimals = 6,
  hideSymbol = false,
  className,
}: TokenAmountProps) {
  const display = `${formatAmount(amount, decimals)}${hideSymbol ? "" : ` ${symbol}`}`;

  if (!usdValue) {
    return (
      <span className={cn("tabular-nums text-sm font-medium", className)}>
        {display}
      </span>
    );
  }

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <span className={cn("tabular-nums text-sm font-medium cursor-default", className)}>
            {display}
          </span>
        </TooltipTrigger>
        <TooltipContent side="bottom" className="text-xs">
          ≈ ${usdValue}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}
